// SectorSource.h - sequential producer of 2352-byte sectors starting at LBA 0.
// The 150-sector pre-gap (LBA -150..-1) is generated by the writer, not the source.
#pragma once
#include "SectorComposer.h"
#include "../core/PolarDitherEngine.h"
#include <cstdint>
#include <vector>

namespace dis {

class SectorSource {
public:
    virtual ~SectorSource() {}
    virtual uint32_t totalSectors() const = 0;      // >= 300 (4 s CD minimum)
    virtual bool next(uint8_t* out2352) = 0;        // sequential
    virtual void rewind() = 0;
};

// Pulls tones from the polar dither engine, one sector (12 cells) at a time.
class ImageSectorSource : public SectorSource {
public:
    ImageSectorSource(PolarDitherEngine& engine, const SectorComposer& composer);
    uint32_t totalSectors() const override { return total_; }
    bool next(uint8_t* out2352) override;
    void rewind() override { eng_.reset(); lba_ = 0; }
private:
    PolarDitherEngine& eng_;
    const SectorComposer& comp_;
    std::vector<uint8_t> tones_;
    uint32_t total_;
    uint32_t lba_;
};

} // namespace dis
